import type { CSSProperties, ReactNode } from "react"

import { cn } from "@/lib/utils"

import { chromeConfig } from "./config"
import GoogleHomePreview from "./google-home-preview"

export type BrowserViewportProps = {
  className?: string
  minHeight?: string | number
  aspectRatio?: string
  src?: string
  alt?: string
  videoSrc?: string
  poster?: string
  autoPlay?: boolean
  children?: ReactNode
}

export default function BrowserViewport({
  className,
  minHeight = chromeConfig.defaultViewportMinHeight,
  aspectRatio,
  src,
  alt = "",
  videoSrc,
  poster,
  autoPlay = true,
  children,
}: BrowserViewportProps) {
  const style = {
    ...(aspectRatio ? { aspectRatio } : {}),
    minHeight: typeof minHeight === "number" ? `${minHeight}px` : minHeight,
  } satisfies CSSProperties

  return (
    <div
      className={cn(
        "relative w-full overflow-hidden bg-(--gc-viewport-bg)",
        className
      )}
      style={style}
    >
      {children ? (
        <div className="gc-viewport-slot absolute inset-0 flex size-full overflow-hidden">
          {children}
        </div>
      ) : videoSrc ? (
        <video
          className="absolute inset-0 block size-full border-none object-cover object-center"
          src={videoSrc}
          poster={poster}
          muted
          loop
          playsInline
          autoPlay={autoPlay}
        />
      ) : src ? (
        // eslint-disable-next-line @next/next/no-img-element -- registry block; consumers may swap for next/image
        <img
          className="absolute inset-0 block size-full border-none object-cover object-center"
          src={src}
          alt={alt}
        />
      ) : (
        <GoogleHomePreview className="absolute inset-0" />
      )}
    </div>
  )
}

import GoogleHomePreview from "./google-home-preview"
import PageLoadingBar from "./page-loading-bar"
import type { PageLoadPhase } from "./use-simulated-page-load"

type ChromeViewportDefaultProps = {
  progress: number
  phase: PageLoadPhase
}

export default function ChromeViewportDefault({
  progress,
  phase,
}: ChromeViewportDefaultProps) {
  return (
    <div className="relative size-full">
      <PageLoadingBar progress={progress} visible={phase === "loading"} />
      <GoogleHomePreview className="absolute inset-0" />
    </div>
  )
}

type PageLoadingBarProps = {
  progress: number
  visible: boolean
}

export default function PageLoadingBar({ progress, visible }: PageLoadingBarProps) {
  if (!visible) return null

  return (
    <div
      className="pointer-events-none absolute inset-x-0 top-0 z-10 h-px overflow-hidden"
      aria-hidden
    >
      <div
        className="h-full bg-[#1a73e8] dark:bg-[#8ab4f8]"
        style={{ width: `${Math.min(100, progress)}%` }}
      />
    </div>
  )
}

"use client"

import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from "react"

export type PageLoadPhase = "idle" | "loading" | "loaded"

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

/** Chrome-like load curve: fast start, slow crawl, quick finish. */
function chromeLoadProgress(elapsedMs: number): number {
  if (elapsedMs < 350) {
    return (elapsedMs / 350) * 68
  }
  if (elapsedMs < 1400) {
    const t = (elapsedMs - 350) / 1050
    return 68 + t * 22
  }
  if (elapsedMs < 1650) {
    const t = (elapsedMs - 1400) / 250
    return 90 + t * 10
  }
  return 100
}

export function useSimulatedPageLoad() {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer,
  )
  const [phase, setPhase] = useState<PageLoadPhase>("idle")
  const [progress, setProgress] = useState(0)
  const rafRef = useRef<number>(0)
  const startRef = useRef<number>(0)

  const reset = useCallback(() => {
    cancelAnimationFrame(rafRef.current)
    setPhase("idle")
    setProgress(0)
  }, [])

  const startLoading = useCallback(() => {
    cancelAnimationFrame(rafRef.current)
    if (reducedMotion) {
      setPhase("loaded")
      setProgress(100)
      return
    }
    setPhase("loading")
    setProgress(0)
    startRef.current = performance.now()

    const tick = (now: number) => {
      const elapsed = now - startRef.current
      const next = chromeLoadProgress(elapsed)
      setProgress(next)
      if (next >= 100) {
        setPhase("loaded")
        return
      }
      rafRef.current = requestAnimationFrame(tick)
    }
    rafRef.current = requestAnimationFrame(tick)
  }, [reducedMotion])

  useEffect(() => () => cancelAnimationFrame(rafRef.current), [])

  useEffect(() => {
    if (reducedMotion) startLoading()
  }, [reducedMotion, startLoading])

  return { phase, progress, startLoading, reset }
}

