import { cn } from "@/lib/utils"

type OmniboxTypingTextProps = {
  displayText: string
  showCursor: boolean
  caretSolid: boolean
  textClassName?: string
  caretClassName?: string
}

export default function OmniboxTypingText({
  displayText,
  showCursor,
  caretSolid,
  textClassName = "min-w-0 truncate text-[inherit] leading-[inherit] text-[var(--gc-omnibox-fg)] select-none",
  caretClassName = "gc-omnibox-caret",
}: OmniboxTypingTextProps) {
  return (
    <span
      className="inline-flex min-h-[calc(0.8125rem*1.2)] min-w-0 flex-1 items-center overflow-hidden text-3.25 leading-[1.2]"
      aria-hidden
    >
      <span className={cn(textClassName, !displayText && "opacity-0")}>
        {displayText || "\u200b"}
      </span>
      {showCursor ? (
        <span
          className={cn(
            caretClassName,
            "ml-px inline-block h-[calc(0.8125rem*1.2)] w-px shrink-0 bg-(--gc-omnibox-caret)",
            caretSolid && `${caretClassName}--solid`
          )}
          aria-hidden
        />
      ) : null}
    </span>
  )
}

import { useEffect, useLayoutEffect, useReducer, useRef, useSyncExternalStore } from "react"

import {
  BETWEEN_MS,
  DELETE_CHAR_MS_FAST,
  DELETE_CHAR_MS_SLOW,
  HOLD_MS,
  START_DELAY_MS,
  TYPE_CHAR_MS_FAST,
  TYPE_CHAR_MS_SLOW,
} from "./typing-animation"

export type OmniboxTypingOptions = {
  /** Phrases to cycle through in the omnibox */
  prompts: readonly string[]
  typeCharMsFast?: number
  typeCharMsSlow?: number
  deleteCharMsFast?: number
  deleteCharMsSlow?: number
  holdMs?: number
  betweenMs?: number
  startDelayMs?: number
  /** Fired when a phrase finishes typing (entering hold). */
  onTypedComplete?: () => void
}

type Phase = "idle" | "typingIn" | "hold" | "typingOut" | "between"

type State = {
  phase: Phase
  promptIdx: number
  charIdx: number
}

type Action =
  | { type: "ADVANCE_CHAR" }
  | { type: "SET_PHASE"; phase: Phase; charIdx?: number; promptIdx?: number }
  | { type: "REWIND_CHAR" }

function jitter(ms: number, spread = 0.1): number {
  const delta = ms * spread * (Math.random() * 2 - 1)
  return Math.max(10, Math.round(ms + delta))
}

function typeDelayMs(charIdx: number, len: number, fast: number, slow: number): number {
  if (len <= 0) return slow
  const t = charIdx / len
  const ease = Math.pow(1 - t, 0.32)
  return jitter(Math.round(fast + (slow - fast) * ease))
}

function deleteDelayMs(charIdx: number, len: number, fast: number, slow: number): number {
  if (len <= 0) return slow
  const t = charIdx / len
  const ease = Math.pow(t, 0.4)
  return jitter(Math.round(fast + (slow - fast) * ease))
}

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

export function useOmniboxTyping({
  prompts,
  typeCharMsFast = TYPE_CHAR_MS_FAST,
  typeCharMsSlow = TYPE_CHAR_MS_SLOW,
  deleteCharMsFast = DELETE_CHAR_MS_FAST,
  deleteCharMsSlow = DELETE_CHAR_MS_SLOW,
  holdMs = HOLD_MS,
  betweenMs = BETWEEN_MS,
  startDelayMs = START_DELAY_MS,
  onTypedComplete,
}: OmniboxTypingOptions) {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer,
  )

  const [state, dispatch] = useReducer(reducer, {
    phase: "idle",
    promptIdx: 0,
    charIdx: 0,
  })

  const { phase, promptIdx, charIdx } = state
  const text = prompts[promptIdx] ?? ""
  const len = text.length

  const displayText = reducedMotion ? (prompts[0] ?? "") : text.slice(0, charIdx)
  const showCursor = !reducedMotion
  const caretSolid = phase === "typingIn" || phase === "typingOut"
  const isActive =
    !reducedMotion &&
    (phase === "typingIn" || phase === "hold" || phase === "typingOut" || charIdx > 0)

  const prevPhaseRef = useRef<Phase>(phase)

  useEffect(() => {
    const prev = prevPhaseRef.current
    prevPhaseRef.current = phase

    if (reducedMotion) return
    if (phase === "hold" && prev !== "hold") onTypedComplete?.()
  }, [phase, reducedMotion, onTypedComplete])

  useLayoutEffect(() => {
    if (reducedMotion || prompts.length === 0) return

    let t: ReturnType<typeof setTimeout>

    switch (phase) {
      case "idle":
        t = setTimeout(() => dispatch({ type: "SET_PHASE", phase: "typingIn" }), startDelayMs)
        break

      case "typingIn":
        if (charIdx < len) {
          t = setTimeout(
            () => dispatch({ type: "ADVANCE_CHAR" }),
            typeDelayMs(charIdx, len, typeCharMsFast, typeCharMsSlow),
          )
        } else {
          dispatch({ type: "SET_PHASE", phase: "hold" })
        }
        break

      case "hold":
        t = setTimeout(() => dispatch({ type: "SET_PHASE", phase: "typingOut" }), holdMs)
        break

      case "typingOut":
        if (charIdx > 0) {
          t = setTimeout(
            () => dispatch({ type: "REWIND_CHAR" }),
            deleteDelayMs(charIdx, len, deleteCharMsFast, deleteCharMsSlow),
          )
        } else {
          dispatch({ type: "SET_PHASE", phase: "between", charIdx: 0 })
        }
        break

      case "between":
        t = setTimeout(() => {
          const next = (promptIdx + 1) % prompts.length
          dispatch({
            type: "SET_PHASE",
            phase: "typingIn",
            charIdx: 0,
            promptIdx: next,
          })
        }, betweenMs)
        break
    }

    return () => clearTimeout(t)
  }, [
    reducedMotion,
    phase,
    charIdx,
    len,
    promptIdx,
    prompts.length,
    typeCharMsFast,
    typeCharMsSlow,
    deleteCharMsFast,
    deleteCharMsSlow,
    holdMs,
    betweenMs,
    startDelayMs,
  ])

  return { displayText, showCursor, caretSolid, isActive }
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "ADVANCE_CHAR":
      return { ...state, charIdx: state.charIdx + 1 }
    case "REWIND_CHAR":
      return { ...state, charIdx: Math.max(0, state.charIdx - 1) }
    case "SET_PHASE":
      return {
        phase: action.phase,
        charIdx: action.charIdx ?? state.charIdx,
        promptIdx: action.promptIdx ?? state.promptIdx,
      }
    default:
      return state
  }
}

export const chromeConfig = {
  /** Content area min-height — Windows mockup uses a larger value so total shell height matches */
  defaultViewportMinHeight: "32rem",
  tabTitle: "New Tab",
  omniboxPlaceholder: "Search Google or type a URL",
  /** Default omnibox typewriter phrases — pass your own to `GoogleChrome` for SaaS demos */
  omniboxTypingPrompts: ["facebook.com"] as const,
  bookmarksAppsLabel: "Apps",
  profileInitial: "j",
  profileBg: "#14b8a6",
} as const

/** Eased type speed (ms per character) */
export const TYPE_CHAR_MS_SLOW = 72
export const TYPE_CHAR_MS_FAST = 28

/** Eased delete speed (ms per character) */
export const DELETE_CHAR_MS_SLOW = 42
export const DELETE_CHAR_MS_FAST = 14

/** Pause on full phrase before deleting */
export const HOLD_MS = 2200

/** Pause after clearing before typing again */
export const BETWEEN_MS = 420

/** Pause before the first keystroke (simulates focus / click) */
export const START_DELAY_MS = 680

/* google-chrome — theme tokens, traffic-light hover, caret blink, viewport slot children */

